ee:variables.ee:set-variable:
if(!isEmpty(attributes.queryParams.state)) (
	"select count(*) as count, case_type, state from cvd_case_master where state = '" ++ upper(attributes.queryParams.state) ++ "' group by case_type, state"
) else (
	"select count(*) as count, case_type, state from cvd_case_master group by case_type, state"
)

ee:message.ee:set-payload:
%dw 2.0
output application/json

fun vaccinatedByState(state) = 
    (payload filter (($.STATE == state as String) and ($.CASE_TYPE == "vaccinated")) map {
        COUNT: $.COUNT as Number default 0
    })[0] default { COUNT: 0 }

---
((payload groupBy($.STATE) mapObject {
    caseReports: {
        state: $$,
        reports: {
            total: ($.COUNT default 0 reduce ($ + $$)) - ((vaccinatedByState($$).COUNT) as Number default 0),
            ($ orderBy($.CASE_TYPE) map {
                ($.CASE_TYPE): $.COUNT as Number default 0
            })
        }
    }
}).*caseReports) default []
